func recallTokenLimit(tokens int, sessionStart bool) int {
	if tokens <= 0 {
		if sessionStart {
			tokens = 1800
		} else {
			tokens = 600
		}
	}
	return min(max(tokens, 64), 8192)
}

func assertionTimestamp(value string) bool {
	if value == "" {
		return true
	}
	if len(value) != 19 && len(value) != 20 {
		return false
	}
	if len(value) == 20 && value[19] != 'Z' {
		return false
	}
	normalized := strings.ReplaceAll(strings.TrimSuffix(value, "Z"), "T", " ")
	stamp, err := time.Parse("2006-01-02 15:04:05", normalized)
	return err == nil && stamp.Year() > 0 && stamp.Format("2006-01-02 15:04:05") == normalized
}

func typedEstimate(text string) int {
	if text == "" {
		return 0
	}
	return len(text)/4 + 1
}

func coherentPredecessor(current, old assertionHit) bool {
	if current.PriorVersionID != old.StableID || current.Subject != old.Subject || current.Relation != old.Relation || current.Object == old.Object || !old.Historical {
		return false
	}
	start, ok := evidenceTime(current.AssertedAt)
	if !ok {
		return false
	}
	end, ok := evidenceTime(old.SupersededAt)
	if !ok || end.After(start) {
		return false
	}
	before, ok := evidenceTime(old.AssertedAt)
	if !ok || before.After(start) {
		return false
	}
	// If both world-time bounds were stated, they must also be ordered. Belief
	// corrections alone do not invent a migration date.
	if old.ValidUntil != "" && current.ValidFrom != "" {
		end, ok = evidenceTime(old.ValidUntil)
		if !ok {
			return false
		}
		start, ok = evidenceTime(current.ValidFrom)
		if !ok || end.After(start) {
			return false
		}
	}
	return true
}

