	if len(families) == 0 || len(families) > 16 {
		return nil
	}
	result := []string{}
	seen := map[string]bool{}
	for _, family := range families {
		if !strings.HasPrefix(family, "sha256:") || !receiptDigestValid(strings.TrimPrefix(family, "sha256:")) {
			return nil
